        if (this.state.strict && node.id) {
          this.checkLVal(
            node.id,
            "function name",
            BIND_OUTSIDE,
            undefined,
            undefined,
            strictModeChanged,
          );
        }
      },
    );
    this.prodParam.exit();
    this.expressionScope.exit();
    this.state.labels = oldLabels;
